inline double interp1(const double* x, const double* y, std::size_t n, double q) {
  if (q <= x[0]) return y[0];
  if (q >= x[n-1]) return y[n-1];
  const double* upper = std::upper_bound(x, x+n, q);
  const std::size_t hi = static_cast<std::size_t>(upper-x);
  const std::size_t lo = hi-1;
  const double t = (q-x[lo])/(x[hi]-x[lo]);
  return y[lo] + t*(y[hi]-y[lo]);
}

inline double interp2(const double* rows, std::size_t nr, const double* cols,
                      std::size_t nc, const double* values, double qr, double qc) {
  std::size_t r1 = 0, c1 = 0;
  while (r1+1 < nr && qr > rows[r1+1]) ++r1;
  while (c1+1 < nc && qc > cols[c1+1]) ++c1;
  const std::size_t r2 = std::min(r1+1, nr-1), c2 = std::min(c1+1, nc-1);
  const double tr = r1 == r2 ? 0.0 : std::clamp((qr-rows[r1])/(rows[r2]-rows[r1]), 0.0, 1.0);
  const double tc = c1 == c2 ? 0.0 : std::clamp((qc-cols[c1])/(cols[c2]-cols[c1]), 0.0, 1.0);
  const double a = values[r1*nc+c1] + tc*(values[r1*nc+c2]-values[r1*nc+c1]);
  const double b = values[r2*nc+c1] + tc*(values[r2*nc+c2]-values[r2*nc+c1]);
  return a + tr*(b-a);
}

